 {
 	struct epoll_event e;
@@ -760,7 +778,7 @@ TEST(epoll15)
 	ASSERT_EQ(epoll_ctl(ctx.efd[0], EPOLL_CTL_ADD, ctx.sfd[2], events), 0);
 
 	ctx.main = pthread_self();
